public static class DiscountPolicy
{
    public static int TotalDiscountFor(LoyaltyTier tier, string? promoCode, int subtotalCents)
    {
        var loyaltyCents = LoyaltyDiscountPolicy.DiscountFor(tier, subtotalCents);
        var promoCents = PromoCodePolicy.DiscountFor(promoCode, subtotalCents - loyaltyCents);
        return Math.Min(loyaltyCents + promoCents, subtotalCents);
    }
}
